    value: object


@dataclass(frozen=True)
class Comma(Filter):
    """Concatenate the output streams of two filters."""

    left: Filter
    right: Filter


@dataclass(frozen=True)
class Raise(Filter):
    """Raise a jq runtime error when evaluated."""

    message: str = "error"


@dataclass(frozen=True)
class Array(Filter):
    """Collect a filter's generated values into an array."""

    expression: Filter


@dataclass(frozen=True)
class Limit(Filter):
    """Keep at most ``count`` values from a filter stream."""

    count: int
    expression: Filter

@dataclass(frozen=True)
class Pipe(Filter):
    left: Filter
    right: Filter

@dataclass(frozen=True)
class StringTemplate(Filter):
